<?php
declare(strict_types=1);
require __DIR__.'/canvas-projects.php';
require_once $root.'/api/canvas-access-core.php';
$uid=(int)$user['id'];$template=['canvas_kind'=>'custom','track_id'=>'','title'=>'My data display','html'=>'<section class="sf-dataset-my_purchases"></section>','css'=>''];
$first=sf_agent_scene_history_save($uid,$template);$context=['scene_id'=>$first['id']];
$access=sf_canvas_access_summary($user,$context);
check($access['requires_consent']&&!$access['permissions'][0]['granted'],'New canvas declares personal data without granting it');
check(!sf_canvas_access_table_exists(),'Summary reads do not create consent tables');
$data=sf_agent_canvas_data_for_scene($user,$first['html'],'',null,null,$context);
check($data['my_purchases']['rows']===[]&&$data['my_purchases']['state']==='consent_required','Authoritative personal data resolver withholds rows until consent');
$allow=$access['fingerprint'];$granted=sf_canvas_access_change($user,$context,'grant',$allow,['canvas.data.my_purchases']);
check(!$granted['requires_consent']&&$granted['permissions'][0]['granted'],'Explicit consent is stored for exact current canvas scope');
require_once $root.'/api/canvas-build-workflow-core.php';
$workflowScene=sf_canvas_build_workflow_scene($user,['candidate_id'=>$first['id']]);
check(isset($workflowScene['canvas_access'])&&!$workflowScene['canvas_access']['requires_consent'],'Normal workflow candidate/apply responses include current viewer access metadata');
check(sf_canvas_access_summary($user,$context)['permissions'][0]['granted'],'Visit reload reuses the same account grant');
$grantRows=sf_canvas_access_export($uid);$originalFields=$grantRows[0]['fields_json'];$fields=json_decode($originalFields,true);
$change=sf_db()->prepare('UPDATE canvas_access_grants SET fields_json=? WHERE user_id=?');
$change->execute([json_encode([...$fields,'retired_field:text']),$uid]);
check(!sf_canvas_access_summary($user,$context)['requires_consent'],'A narrower field schema reuses a previously broader valid grant');
$change->execute([json_encode(array_slice($fields,0,-1)),$uid]);
check(sf_canvas_access_summary($user,$context)['requires_consent'],'A newly requested field outside the stored grant requires consent');
$change->execute([$originalFields,$uid]);

sf_db()->beginTransaction();$inside=sf_agent_canvas_data_for_scene($user,$first['html'],'',null,null,$context);sf_db()->rollBack();
check($inside['my_purchases']['rows']===[]&&$inside['my_purchases']['state']==='unavailable','Private delivery refuses outer transactions with potentially stale authorization snapshots');
rejected(fn()=>sf_canvas_access_summary(['id'=>2],$context),OutOfBoundsException::class,'Another account cannot inspect a private scene or inherit its grants');
check(sf_agent_canvas_data_for_scene($user,$first['html'])['my_purchases']['state']==='consent_required','Omitting the trusted stored context cannot bypass consent');
$revision=sf_agent_scene_history_save($uid,$template,$first['id']);$revisionContext=['scene_id'=>$revision['id']];
check(!sf_canvas_access_summary($user,$revisionContext)['requires_consent'],'Trusted revision with equal scope reuses grants');
$expanded=sf_agent_scene_history_save($uid,array_replace($template,['html'=>$template['html'].'<section class="sf-dataset-my_tickets"></section>']),$revision['id']);
$expandedAccess=sf_canvas_access_summary($user,['scene_id'=>$expanded['id']]);$p=array_column($expandedAccess['permissions'],null,'id');
check($p['canvas.data.my_purchases']['granted']&&!$p['canvas.data.my_tickets']['granted'],'Expanded scope asks only for the new category');
$narrow=sf_agent_scene_history_save($uid,array_replace($template,['html'=>'<section class="scene"></section>']),$expanded['id']);
check(!sf_canvas_access_summary($user,['scene_id'=>$narrow['id']])['requires_consent'],'Narrower revision adds no new consent request');
$independent=sf_agent_scene_history_save($uid,$template+['access_root_id'=>$first['id']]);
check(sf_canvas_access_summary($user,['scene_id'=>$independent['id']])['requires_consent'],'Independent copies ignore caller-supplied lineage and never inherit consent by matching code');
$revoked=sf_canvas_access_change($user,$context,'revoke',$granted['fingerprint'],['canvas.data.my_purchases']);
check($revoked['requires_consent']&&sf_canvas_access_summary($user,$revisionContext)['requires_consent'],'Revocation covers the trusted canvas lineage');
rejected(fn()=>sf_canvas_access_change($user,$context,'grant',$allow,['canvas.data.my_purchases']),SfCanvasAccessConflict::class,'An old Allow request cannot replay after revoke');
rejected(fn()=>sf_canvas_access_change($user,$context,'grant',$revoked['fingerprint'],['canvas.data.my_tickets']),InvalidArgumentException::class,'Undeclared data permissions cannot be granted');
$granted=sf_canvas_access_change($user,$context,'grant',$revoked['fingerprint'],['canvas.data.my_purchases']);
sf_canvas_permission_save(['id'=>9,'role'=>'admin'],1,['canvas.data.my_purchases'=>false]);
check(sf_agent_canvas_data_for_scene($user,$first['html'],'',null,null,$context)===[],'Administrator disablement overrides viewer consent');
$disabled=sf_canvas_access_summary($user,$context);
check(!$disabled['permissions'][0]['enabled']&&$disabled['permissions'][0]['granted'],'Disabled scopes remain inspectable and revocable');
sf_canvas_access_change($user,$context,'revoke',$disabled['fingerprint'],['canvas.data.my_purchases']);
sf_canvas_permission_save(['id'=>9,'role'=>'admin'],2,['canvas.data.my_purchases'=>true]);
check(sf_canvas_access_summary($user,$context)['requires_consent'],'Re-enabling admin permission never restores revoked consent');
$current=sf_canvas_access_summary($user,$context);sf_canvas_access_change($user,$context,'grant',$current['fingerprint'],['canvas.data.my_purchases']);
$rootId=sf_canvas_access_root($uid,$revision['id']);
// Model pre-upgrade rows whose additive lineage column has not been populated.
sf_db()->prepare('UPDATE agent_scene_history SET access_root_id=NULL WHERE user_id=? AND id IN (?,?)')->execute([$uid,$first['id'],$revision['id']]);
check(!sf_canvas_access_summary($user,$revisionContext)['requires_consent'],'Legacy NULL-root lineage reuses its original root grant');
sf_agent_scene_delete($uid,$first['id']);
check(sf_canvas_access_root($uid,$revision['id'])===$rootId&&!sf_canvas_access_summary($user,$revisionContext)['requires_consent'],'Deleting an earlier revision preserves trusted lineage grants');
$orphan=sf_canvas_access_saved($uid);check(count($orphan)===1,'Account controls list saved grants without source disclosure');
sf_agent_scene_delete($uid,$revision['id']);
$rows=sf_canvas_access_revoke_saved($user,$orphan[0]['context_key'],[$orphan[0]['permission_id']]);check($rows===[],'Owner can revoke saved access even after source deletion');
$latest=sf_canvas_access_summary($user,['scene_id'=>$independent['id']]);sf_canvas_access_change($user,['scene_id'=>$independent['id']],'grant',$latest['fingerprint'],['canvas.data.my_purchases']);
check(count(sf_canvas_access_export($uid))===1&&sf_canvas_access_export(2)===[],'Consent export remains account scoped');
$stale=$latest['fingerprint'];$reset=sf_privacy_clear_agent_history($uid);
check(sf_canvas_access_export($uid)===[]&&$reset['canvas_access_grants']===1,'Clearing agent history purges remembered grants');
rejected(fn()=>sf_canvas_access_change($user,['scene_id'=>$independent['id']],'grant',$stale,['canvas.data.my_purchases']),OutOfBoundsException::class,'Late consent cannot recreate cleared scene access');
